
#' \code{get.outs.lut} get the outputs from SCOPE model. This code is for a LUT of simulations
#'
#' @param data.sim  list elements generated by the SCOPE model
#' @param LUT a list of inputs used in the SCOPE model
#' @param path.out  path for saving the main files
#' @param get.plots  is true, intermediate plots will be generated in Plot folder
#' @param nSamples integer. Number of simulations (rows of \code{LUT}/\code{data.sim}) to process.
#' @author Carlos Camino (Ported version into R)
#'
#' @examples
#' \dontrun{
#' get.outs.lut(data.sim, LUT, path.out, get.plots = TRUE, nSamples = 100)
#' }

get.outs.lut <-function(data.sim, LUT,path.out,get.plots, nSamples){

  #if (!require("data.table")) { install.packages("data.table"); require("data.table") }  ### hsdar for PROSAIL

  # Get the current system time
  current_time <- format(Sys.time(), "%Y-%m-%d_%H-%M-%S")

  if (missing(get.plots)){
    get.plots = FALSE
  }


  if (missing(path.out)) {
    path_outs <- 'outs/'
    message('outs/ folder will be used for the SCOPE outputs')


    if (!dir.exists(path_outs)) {
      dir.create(path_outs)
    }

    # Create a folder with the current system time as part of the folder name
    folder_out <- paste(path_outs, current_time, sep = "")
    dir.create(folder_out)

    if (get.plots == T) {
      folder_for_plots <- paste(path_outs, current_time,'/Plots/',sep = "")
      dir.create(folder_for_plots)
    }


  } else {

    path_outs <- path.out
    if (!dir.exists(path_outs)) {
      dir.create(path_outs)
    }

    # Create a folder with the current system time as part of the folder name
    folder_out <- paste(path_outs, current_time, sep = "")
    dir.create(folder_out)

    if (get.plots == T) {
      folder_for_plots <- paste(path_outs, current_time,'/Plots/', sep = "")
      dir.create(folder_for_plots)


    }

  }


  # Create a folder with the current system time as part of the folder name
  folder_out_parameters <- paste(path_outs, current_time,'/Parameters/', sep = "")
  dir.create(folder_out_parameters)

  message <- "the SCOPE model uses the version 2.1 integrated in the SCOPEinR package "
  file_readme <-paste(folder_out_parameters,"/SCOPEversion.txt",sep='')
  writeLines(message, file_readme)
  # save using data.table
  data.table::fwrite(LUT, paste(folder_out_parameters,"/inputLUT.csv",sep=''))


  ##############################################################################################################################
  # 1.1 Get Reflectance ----
  ##############################################################################################################################

  matrix.reflapp<- matrix(nrow = 2162, ncol = nSamples+1)
  matrix.refl<- matrix(nrow = 2162, ncol = nSamples+1)
  matrix.rsd<- matrix(nrow = 2162, ncol = nSamples+1)
  matrix.rso<- matrix(nrow = 2162, ncol = nSamples+1)
  matrix.rdd<- matrix(nrow = 2162, ncol = nSamples+1)
  matrix.rdo<- matrix(nrow = 2162, ncol = nSamples+1)

  for (i in 1:length(data.sim)) {

    if (i ==1){
      wlS <- data.sim[[i]]$data.spectral$wlS
    }
    # Add reflect apparent
    reflapp <- data.sim[[i]]$data.rad$reflapp
    matrix.reflapp[, 1] <- wlS
    matrix.reflapp[, i+1] <- reflapp
    df.reflapp <- as.data.frame(matrix.reflapp)
    # Set column names as n1, n2, n3, ...
    colnames(df.reflapp) <- c("wave", paste0("n.sim", 2:ncol(df.reflapp)-1))


    # Add reflect
    refl <- data.sim[[i]]$data.rad$refl
    matrix.refl[, 1] <- wlS
    matrix.refl[, i+1] <- refl

    df.refl <- as.data.frame(matrix.refl)
    # Set column names as n1, n2, n3, ...
    colnames(df.refl) <- c("wave", paste0("n.sim", 2:ncol(df.refl)-1))

    # Add rsd
    rsd <- data.sim[[i]]$data.rad$rsd
    matrix.rsd[, 1] <- wlS
    matrix.rsd[, i+1] <- rsd

    df.rsd <- as.data.frame(matrix.rsd)
    # Set column names as n1, n2, n3, ...
    colnames(df.rsd) <- c("wave", paste0("n.sim", 2:ncol(df.rsd)-1))

    # Add rso
    rso <- data.sim[[i]]$data.rad$rso
    matrix.rso[, 1] <- wlS
    matrix.rso[, i+1] <- rso
    df.rso <- as.data.frame(matrix.rso)
    # Set column names as n1, n2, n3, ...
    colnames(df.rso) <- c("wave", paste0("n.sim", 2:ncol(df.rso)-1))

    # Add rdd
    rdd <- data.sim[[i]]$data.rad$rdd
    matrix.rdd[, 1] <- wlS
    matrix.rdd[, i+1] <- rdd
    df.rdd <- as.data.frame(matrix.rdd)
    # Set column names as n1, n2, n3, ...
    colnames(df.rdd) <- c("wave", paste0("n.sim", 2:ncol(df.rdd)-1))

    # Add rdo
    rdo <- data.sim[[i]]$data.rad$rdo
    matrix.rdo[, 1] <- wlS
    matrix.rdo[, i+1] <- rdo
    df.rdo <- as.data.frame(matrix.rdo)
    # Set column names as n1, n2, n3, ...
    colnames(df.rdo) <- c("wave", paste0("n.sim", 2:ncol(df.rdo)-1))

  }

  # save using data.table
  data.table::fwrite(df.rsd, paste(folder_out,"/rsd.csv",sep=''))
  data.table::fwrite(df.rso, paste(folder_out,"/rso.csv",sep=''))
  data.table::fwrite(df.rdd, paste(folder_out,"/rdd.csv",sep=''))
  data.table::fwrite(df.rdo, paste(folder_out,"/rdo.csv",sep=''))
  data.table::fwrite(df.refl, paste(folder_out,"/refl.csv",sep=''))
  data.table::fwrite(df.reflapp, paste(folder_out,"/reflapp.csv",sep=''))


  if (get.plots == T) {


    # :::::::::::::::::::::::::::::::::::::::::::::
    # 1.1 Get rdo ----
    # :::::::::::::::::::::::::::::::::::::::::::::

    # Reshape the data frame into a long format
    df_rdo <-df.rdo %>%
      gather(n.sim, value, -wave)

    # Plot all spectra in a single plot
    plot.rdo<-ggplot(df_rdo, aes(x = wave, y = value, color =  n.sim, group =  n.sim)) +
      geom_line(linewidth = 0.5) +
      theme_bw() +
      xlim(400, 2499) +
      ylab("Reflectance (rdo)") +
      theme(legend.position = "none") +
      guides(color = guide_legend(title = NULL))
    ggsave(paste(folder_for_plots,'1-reflectance_rdo.png',sep=''),plot=plot.rdo,
           width = 10, height = 10,  dpi = 300,units = "cm")

    # :::::::::::::::::::::::::::::::::::::::::::::
    # 1.2 Get rdd ----
    # :::::::::::::::::::::::::::::::::::::::::::::

    # Reshape the data frame into a long format
    df_rdd <-df.rdd %>%
      gather(n.sim, value, -wave)

    # Plot all spectra in a single plot
    plot.rdd<-ggplot(df_rdd, aes(x = wave, y = value, color =  n.sim, group =  n.sim)) +
      geom_line(linewidth = 0.5) +
      theme_bw() +
      xlim(400, 2499) +
      ylab("Reflectance (rdd)") +
      theme(legend.position = "none") +
      guides(color = guide_legend(title = NULL))
    ggsave(paste(folder_for_plots,'1-reflectance_rdd.png',sep=''),plot=plot.rdd,
           width = 10, height = 10,  dpi = 300,units = "cm")


    # :::::::::::::::::::::::::::::::::::::::::::::
    # 1.3 Get rso ----
    # :::::::::::::::::::::::::::::::::::::::::::::

    # Reshape the data frame into a long format
    df_rso <-df.rso %>%
      gather(n.sim, value, -wave)

    # Plot all spectra in a single plot
    plot.rso<-ggplot(df_rso, aes(x = wave, y = value, color =  n.sim, group =  n.sim)) +
      geom_line(linewidth = 0.5) +
      theme_bw() +
      xlim(400, 2499) +
      ylab("Reflectance (rso)") +
      theme(legend.position = "none") +
      guides(color = guide_legend(title = NULL))
    ggsave(paste(folder_for_plots,'1-reflectance_rso.png',sep=''),plot=plot.rso,
           width = 10, height = 10,  dpi = 300,units = "cm")


    # :::::::::::::::::::::::::::::::::::::::::::::
    # 1.4 Get rsd ----
    # :::::::::::::::::::::::::::::::::::::::::::::

    # Reshape the data frame into a long format
    df_rsd <-df.rsd %>%
      gather(n.sim, value, -wave)

    # Plot all spectra in a single plot
    plot.rsd<-ggplot(df_rsd, aes(x = wave, y = value, color =  n.sim, group =  n.sim)) +
      geom_line(linewidth = 0.5) +
      theme_bw() +
      xlim(400, 2499) +
      ylab("Reflectance (rsd)") +
      theme(legend.position = "none") +
      guides(color = guide_legend(title = NULL))
    ggsave(paste(folder_for_plots,'1-reflectance_rsd.png',sep=''),plot=plot.rsd,
           width = 10, height = 10,  dpi = 300,units = "cm")

    # :::::::::::::::::::::::::::::::::::::::::::::
    # 1.5 Get refl  ----
    # :::::::::::::::::::::::::::::::::::::::::::::

    # Reshape the data frame into a long format
    df_refl <-df.refl %>%
      gather(n.sim, value, -wave)

    # Plot all spectra in a single plot
    plot.refl<-ggplot(df_refl, aes(x = wave, y = value, color =  n.sim, group =  n.sim)) +
      geom_line(linewidth = 0.5) +
      theme_bw() +
      xlim(400, 2499) +
      ylab("Reflectance (refl)") +
      theme(legend.position = "none") +
      guides(color = guide_legend(title = NULL))
    ggsave(paste(folder_for_plots,'1-reflectance_refl.png',sep=''),plot=plot.refl,
           width = 10, height = 10,  dpi = 300,units = "cm")

    # :::::::::::::::::::::::::::::::::::::::::::::
    # 1.6 Get reflapp ----
    # :::::::::::::::::::::::::::::::::::::::::::::

    # Reshape the data frame into a long format
    df_reflapp <-df.reflapp %>%
      gather(n.sim, value, -wave)

    # Plot all spectra in a single plot
    plot.reflapp<-ggplot(df_reflapp, aes(x = wave, y = value, color =  n.sim, group =  n.sim)) +
      geom_line(linewidth = 0.5) +
      theme_bw() +
      xlim(400, 2499) +
      ylab("Apparent reflectance") +
      theme(legend.position = "none") +
      guides(color = guide_legend(title = NULL))
    ggsave(paste(folder_for_plots,'1-reflappectance_reflapp.png',sep=''),plot=plot.reflapp,
           width = 10, height = 10,  dpi = 300,units = "cm")




  }


  ##############################################################################################################################
  # 1.2 Get Irradiance ----
  ##############################################################################################################################

  matrix.Esun<- matrix(nrow = 2162, ncol = 1+1)
  matrix.Esky<- matrix(nrow = 2162, ncol = 1+1)


  wlS <- data.sim[[1]]$data.spectral$wlS
  i=1
  # Add Esun
  Esun <- data.sim[[1]]$data.rad$Esun_
  matrix.Esun[, 1] <- wlS
  matrix.Esun[, i+1] <- Esun
  df.Esun_ <- as.data.frame(matrix.Esun)
  # Set column names as n1, n2, n3, ...
  colnames(df.Esun_) <- c('wave','Esun')


  # Add Esky
  Esky <- data.sim[[i]]$data.rad$Esky_
  matrix.Esky[, 1] <- wlS
  matrix.Esky[, i+1] <- Esky

  df.Esky_ <- as.data.frame(matrix.Esky)
  # Set column names as n1, n2, n3, ...
  colnames(df.Esky_) <- c("wave", 'Esky')

  # save using data.table
  data.table::fwrite(df.Esun_, paste(folder_out,"/Esun.csv",sep=''))
  data.table::fwrite(df.Esky_, paste(folder_out,"/Esky.csv",sep=''))



  if (get.plots == T) {

    df.irrad <- data.frame(wave=wlS, Esun_ = df.Esun_$Esun,
                           Esky_=df.Esky_$Esky)

    p.irrad<- ggplot(data = df.irrad, aes(x = wave)) +
      geom_line(aes(y = Esun_, color = 'Esun_'), linewidth = 0.5) +
      geom_line(aes(y = Esky_, color = 'Esky_'), linewidth = 0.5) +

      scale_color_manual(name = 'Irradiance',
                         values = c('Esun_' = 'orange',
                                    'Esky_' ='grey')) +

      theme_bw() + xlim(400,2499) +
      theme(legend.position = "top") +ylab("Irradiance") +
      guides(color = guide_legend(title = NULL))

    ggsave(paste(folder_for_plots,'2-Irradiance.png',sep=''),plot=p.irrad,
           width = 10, height = 10,  dpi = 300,units = "cm")


  }

  ##############################################################################################################################
  # 1.3 Get Radiance spectrum  excluding/adding fluorescence  (W m-2 um-1 sr-1)   ----
  ##############################################################################################################################

  matrix.Lotot_<- matrix(nrow = 2162, ncol = nSamples+1)
  matrix.Lototf_<- matrix(nrow = 2162, ncol = nSamples+1)

  for (i in 1:length(data.sim)) {

    if (i ==1){
      wlS <- data.sim[[i]]$data.spectral$wlS
    }
    # Add Lotot_
    Lotot_ <- data.sim[[i]]$data.rad$Lotot_
    matrix.Lotot_[, 1] <- wlS
    matrix.Lotot_[, i+1] <- Lotot_
    df.Lotot_<- as.data.frame(matrix.Lotot_)
    # Set column names as n1, n2, n3, ...
    colnames(df.Lotot_) <- c("wave", paste0("n.sim", 2:ncol(df.Lotot_)-1))


    # Add Lototf_
    Lototf_ <- data.sim[[i]]$data.rad$Lototf_
    matrix.Lototf_[, 1] <- wlS
    matrix.Lototf_[, i+1] <- Lototf_
    df.Lototf_<- as.data.frame(matrix.Lototf_)
    # Set column names as n1, n2, n3, ...
    colnames(df.Lototf_) <- c("wave", paste0("n.sim", 2:ncol(df.Lototf_)-1))


  }

  # save using data.table
  data.table::fwrite(df.Lotot_, paste(folder_out,"/Lo_spectrum.csv",sep=''))
  data.table::fwrite(df.Lototf_, paste(folder_out,"/Lo_spectrum_includingF.csv",sep=''))

  if (get.plots == T) {


    # :::::::::::::::::::::::::::::::::::::::::::::
    # 1.1 Get Lotot_ ----
    # :::::::::::::::::::::::::::::::::::::::::::::

    # Reshape the data frame into a long format
    df_Lotot_ <-df.Lotot_ %>%
      gather(n.sim, value, -wave)

    # Plot all spectra in a single plot
    plot.Lotot_<-ggplot(df_Lotot_, aes(x = wave, y = value, color =  n.sim, group =  n.sim)) +
      geom_line(linewidth = 0.5) +
      theme_bw() +
      xlim(400, 900) +
      ylab("Radiance") +
      theme(legend.position = "none") +
      guides(color = guide_legend(title = NULL))


    ggsave(paste(folder_for_plots,'3-Radiance_excluding_Fluorescence.png',sep=''),plot=plot.Lotot_,
           width = 10, height = 10,  dpi = 300,units = "cm")

    # :::::::::::::::::::::::::::::::::::::::::::::
    # 1.2 Get Lototf_ ----
    # :::::::::::::::::::::::::::::::::::::::::::::

    # Reshape the data frame into a long format
    df_Lototf_ <-df.Lototf_ %>%
      gather(n.sim, value, -wave)

    # Plot all spectra in a single plot
    plot.Lototf_<-ggplot(df_Lototf_, aes(x = wave, y = value, color =  n.sim, group =  n.sim)) +
      geom_line(linewidth = 0.5) +
      theme_bw() +
      xlim(400, 900) +
      ylab("Radiance") +
      theme(legend.position = "none") +
      guides(color = guide_legend(title = NULL))


    ggsave(paste(folder_for_plots,'3-Radiance_adding_Fluorescence.png',sep=''),plot=plot.Lototf_,
           width = 10, height = 10,  dpi = 300,units = "cm")


  }



  ##############################################################################################################################
  # 1.4 Get Radiation  ----
  ##############################################################################################################################



  matrix.radiation<- matrix(nrow = nSamples, ncol = 5)


  for (i in 1:length(data.sim)) {

    # Add radiation data
    n.sim <-i
    Rin <- data.sim[[i]]$data.meteo$Rin
    Rli <- data.sim[[i]]$data.meteo$Rli
    Eouto <- data.sim[[i]]$data.rad$Eouto
    Eoutte <- data.sim[[i]]$data.rad$Eoutte

    matrix.radiation[i,] <- c(n.sim,Rin,Rli,Eouto,Eoutte)

    df.radiation<- as.data.frame(matrix.radiation)
    # Set column names as n1, n2, n3, ...
    colnames(df.radiation) <- c('n.sim','ShortIn','ShortLong','HemisOutIn','HemisOutLong')
  }

  # save using data.table
  data.table::fwrite(df.radiation, paste(folder_out,"/radiation.csv",sep=''))


  df.radiation.units <- data.frame(ShortIn = 'W m-2', ShortLong = 'W m-2',
                                   HemisOutIn = 'W m-2', HemisOutLong = 'W m-2',
                                   Lo = 'W m-2 sr -1', Lot = 'W m-2 sr -1', Lote = 'W m-2 sr -1')


  # save using data.table
  data.table::fwrite(df.radiation.units, paste(folder_out,"/radiation_units.csv",sep=''))


  ##############################################################################################################################
  # 1.5 Get ApAR values  ----
  ##############################################################################################################################



  matrix.apar<- matrix(nrow = 21, ncol = nSamples)

  for (i in 1:length(data.sim)) {

    # Add number of sim
    n.sim <-i

    # EPAR and PAR
    iPAR =  data.sim[[i]]$data.rad[['PAR']] ## units in umol m-2 s-1
    iPARE =  data.sim[[i]]$data.rad[['EPAR']] ## units in W m-2
    ## LAI sunit/sgaded
    LAIsunlit =  data.sim[[i]]$data.canopy[['LAIsunlit']] ## m2 m-2
    LAIshaded =  data.sim[[i]]$data.canopy[['LAIshaded']] ## m2 m-2
    # Total aPAR
    aPARTot =  data.sim[[i]]$data.canopy[['Pntot']] ## units in umol m-2 s-1
    aPARTotSun =  data.sim[[i]]$data.canopy[['Pnsun']] ## units in umol m-2 s-1
    aPARTotShaded =  data.sim[[i]]$data.canopy[['Pnsha']] ## units in umol m-2 s-1

    ## Total aPAR Cab
    aPARCabTot =  data.sim[[i]]$data.canopy[['Pntot_Cab']] ## units in umol m-2 s-1
    aPARCabSun =  data.sim[[i]]$data.canopy[['Pnsun_Cab']] ## units in umol m-2 s-1
    aPARCabShaded =  data.sim[[i]]$data.canopy[['Pnsha_Cab']] ## units in umol m-2 s-1

    ## Total aPAR Car
    aPARCarTot =  data.sim[[i]]$data.canopy[['Pntot_Car']] ## units in umol m-2 s-1
    aPARCarSun =  data.sim[[i]]$data.canopy[['Pnsun_Car']] ## units in umol m-2 s-1
    aPARCarShaded =  data.sim[[i]]$data.canopy[['Pnsha_Car']] ## units in umol m-2 s-1

    # Total aPAR E
    aPARTotE =  data.sim[[i]]$data.canopy[['Rntot_PAR']] ## units in W m-2
    aPARTotSunE =  data.sim[[i]]$data.canopy[['Rnsun_PAR']] ##  units in W m-2
    aPARTotShadedE =  data.sim[[i]]$data.canopy[['Rnsha_PAR']] ## units in m-2

    # Total aPAR E Cab
    aPARTotCabE =  data.sim[[i]]$data.canopy[['Rntot_Cab']] ## units in W m-2
    aPARTotSunCabE =  data.sim[[i]]$data.canopy[['Rnsun_Car']]##  units in W m-2
    aPARTotShadedCabE =  data.sim[[i]]$data.canopy[['Rnsha_Car']] ## units in W m-2

    # Total aPAR E Car
    aPARTotCarE =  data.sim[[i]]$data.canopy[['Rntot_Car']] ## units in W m-2
    aPARTotSunCarE =  data.sim[[i]]$data.canopy[['Rnsun_Car']] ##  units in W m-2
    aPARTotShadedCarE =  data.sim[[i]]$data.canopy[['Rnsha_Car']]## units in W m-2

    data.apar <-rbind(iPAR, iPARE,
          LAIsunlit, LAIshaded,
          aPARTot, aPARTotSun, aPARTotShaded,
          aPARCabTot, aPARCabSun, aPARCabShaded,
          aPARCarTot, aPARCarSun, aPARCarShaded,
          aPARTotE, aPARTotSunE, aPARTotShadedE,
          aPARTotCabE, aPARTotSunCabE, aPARTotShadedCabE,
          aPARTotCarE, aPARTotSunCarE,aPARTotShadedCarE)
    matrix.apar[,i] <- data.apar

  }

  df.apar<- as.data.frame(matrix.apar)
  var.names <-rownames(data.apar)
  df.apar<-cbind(var.names,df.apar)
  # Set column names as n1, n2, n3, ...
  colnames(df.apar) <- c("Variable", paste0("n.sim", 2:ncol(df.apar)-1))

  # save using data.table
  data.table::fwrite(df.apar, paste(folder_out,"/aPAR.csv",sep=''))

  ##############################################################################################################################
  # 1.6 Get resistance values  ----
  ##############################################################################################################################

  matrix.resistance<- matrix(nrow = 4, ncol = nSamples)

  for (i in 1:length(data.sim)) {

    ra = data.sim[[i]]$resist_out[['raws']] ## units in s m-1
    raforSoil = data.sim[[i]]$resist_out[['rss']] ## units in s m-1
    rss = data.sim[[i]]$resist_out[['rss']] ## units in s m-1
    ustar = data.sim[[i]]$resist_out[['ustar']] ## units in m2 s-1

    data.resistance <-rbind(ra, raforSoil,rss,ustar)
    matrix.resistance[,i] <- data.resistance

  }
  df.resistance <- as.data.frame(matrix.resistance)
  var.names <-rownames(df.resistance)
  df.resistance<-cbind(var.names,df.resistance)
  # Set column names as n1, n2, n3, ...
  colnames(df.resistance) <- c("Variable", paste0("n.sim", 2:ncol(df.resistance)-1))

  # save using data.table
  data.table::fwrite(df.resistance, paste(folder_out,"/resistance.csv",sep=''))

  df.resistance.units <-data.frame(ra = 's m-1', raforSoil = 's m-1',
                                   rss = 's m-1', ustar ='m2 s-1')

  # save using data.table
  data.table::fwrite(df.resistance.units, paste(folder_out,"/resistance_units.csv",sep=''))

  ##############################################################################################################################
  # 1.7 Get vegetation values  ----
  ##############################################################################################################################


  matrix.vegetation<- matrix(nrow = 6, ncol = nSamples)

  for (i in 1:length(data.sim)) {

    Photosintesis = data.sim[[i]]$data.canopy[['A']] ## units in umol m-2 s-1
    Electron_transport = data.sim[[i]]$data.canopy[['Ja']] ## units in umol m-2 s-1
    NPQ_energy = data.sim[[i]]$data.canopy[['ENPQ']] ## units in W m-2
    NPQ_photon = data.sim[[i]]$data.canopy[['PNPQ']] ## units in umol photons-1
    LST = data.sim[[i]]$data.canopy[['LST']] ## units in K
    emis = data.sim[[i]]$data.canopy[['emis']] ##  no units

    data.vegetation <-rbind(Photosintesis, Electron_transport,NPQ_energy,NPQ_photon,LST,emis)
    matrix.vegetation[,i] <- data.vegetation

  }
  df.vegetation <- as.data.frame(matrix.vegetation)
  var.names <-rownames(df.vegetation)
  df.vegetation<-cbind(var.names,df.vegetation)
  # Set column names as n1, n2, n3, ...
  colnames(df.vegetation) <- c("Variable", paste0("n.sim", 2:ncol(df.vegetation)-1))


  data.table::fwrite(df.vegetation, paste(folder_out,"/vegatation.csv",sep=''))

